// Versioned requirements from Docs/Development/RELEASE_UAT_PLAYBOOK.md v1.0.
// This is a coverage contract, not a claim that any existing test satisfies it.
export const CELLS = ["sqlite-single", "sqlite-multi", "pg-single", "pg-multi"]
export const SURFACES = ["web", "extension-options", "extension-sidepanel", "cross-surface"]
export const PHASES = ["fresh-state", "clean-install", "supported-upgrade"]
const MULTI = ["sqlite-multi", "pg-multi"]
const FRESH = ["fresh-state", "clean-install"]
const DLU = ["D", "L", "U"]
const DU = ["D", "U"]

function flow(id, title, modes, needs, fixtures, principal, recovery, applicability = {}) {
  const scope = { cells: CELLS, surfaces: ["web"], phases: PHASES, ...applicability }
  return { id, title, version: "1.0", modes, needs, fixtures, ...scope,
    variants: [["principal", principal], ["recovery", recovery]].flatMap(([kind, entries]) =>
      entries.map(([variant, assertion, overrides = {}]) => ({
        id: variant, kind, assertions: [assertion], modes, needs, fixtures, ...scope, ...overrides,
      }))),
  }
}

